# /// script
# requires-python = ">=3.12"
# dependencies = []
# ///
"""Write docs/CODE_MAP.md: one line per module with its path, docstring summary and public names.

An agent reads the map instead of opening files to find where things live. Copy into scripts/,
run `uv run scripts/code_map.py` after adding or renaming modules, and add
`uv run scripts/code_map.py --check` to CI so a stale map fails the build.
"""

from __future__ import annotations

import argparse
import ast
import sys
from pathlib import Path

MAX_NAMES = 8
HEADER = (
    "# Code map\n\n"
    "Generated by `scripts/code_map.py`; do not edit. One line per module: path, docstring "
    "summary, public names.\n\n"
)


def public_names(tree: ast.Module) -> list[str]:
    """`__all__` when the module sets it to a list of strings, else top-level defs and classes."""
    for node in tree.body:
        if isinstance(node, ast.Assign) and any(
            isinstance(t, ast.Name) and t.id == "__all__" for t in node.targets
        ):
            try:
                value = ast.literal_eval(node.value)
            except ValueError:
                break
            if isinstance(value, list | tuple) and all(isinstance(v, str) for v in value):
                return list(value)
    kinds = (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)
    return [n.name for n in tree.body if isinstance(n, kinds) and not n.name.startswith("_")]


def module_line(path: Path, root: Path) -> str:
    line = f"- `{path.relative_to(root).as_posix()}`"
    try:
        tree = ast.parse(path.read_text(encoding="utf-8"))
    except SyntaxError:
        return f"{line}: (syntax error)"
    summary = ((ast.get_docstring(tree) or "").strip().splitlines() or [""])[0].strip()
    names = public_names(tree)
    if len(names) > MAX_NAMES:
        names = [*names[:MAX_NAMES], f"and {len(names) - MAX_NAMES} more"]
    listed = ", ".join(names)
    if summary and listed:
        return f"{line}: {summary} Public: {listed}"
    return f"{line}: {summary or listed}" if summary or listed else line


def module_lines(src: Path, root: Path) -> list[str]:
    return [module_line(path, root) for path in sorted(src.rglob("*.py"))]


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--root", type=Path, default=Path.cwd(), help="project folder")
    parser.add_argument("--src", default="src", help="source folder, relative to --root")
    parser.add_argument("--out", default="docs/CODE_MAP.md", help="map file, relative to --root")
    parser.add_argument("--check", action="store_true", help="fail if the map is out of date")
    args = parser.parse_args(argv)
    root: Path = args.root.resolve()
    src, out = root / args.src, root / args.out
    if not src.is_dir():
        print(f"code_map: no source folder at {src}", file=sys.stderr)
        return 2
    text = HEADER + "\n".join(module_lines(src, root)) + "\n"
    if args.check:
        current = out.read_text(encoding="utf-8") if out.is_file() else ""
        if current != text:
            print(f"code_map: {args.out} is out of date; run scripts/code_map.py", file=sys.stderr)
            return 1
        return 0
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(text, encoding="utf-8")
    return 0


if __name__ == "__main__":
    sys.exit(main())
